"""A–H protocol cases against the real browser, physical engine and retained saves."""
import unittest
from test_living_ship_integration import LivingShipIntegration
class ObservationIntegration(LivingShipIntegration):
 def test_protocol_iris_search_approach_conversation_and_failure(self):
  p=self.page();self.configure(p,"""s.remoteCore.autonomyEnabled=false;const iris=s.crew.find(q=>q.name==='Iris Bell');iris.room=iris.target='C05';iris.route=[];iris.nav=null;iris.task=iris.goal='Seeking a conversation';iris.taskMinutes=30;iris.social=10;iris.energy=90;const frank=s.crew[0];frank.room=frank.target='C05';frank.route=[];frank.nav=null;frank.task=frank.goal='Inspecting machinery';frank.taskMinutes=80;frank.social=10;frank.energy=90;""")
  self.advance(p,1);self.assertEqual(next(q for q in self.snap(p)['crew'] if q['name']=='Iris Bell')['socialSearch']['phase'],'looking');self.advance(p,2);self.assertEqual(next(q for q in self.snap(p)['crew'] if q['name']=='Iris Bell')['socialSearch']['phase'],'approaching');self.advance(p,3);s=self.snap(p);iris=next(q for q in s['crew'] if q['name']=='Iris Bell');self.assertEqual(iris['socialSearch']['phase'],'talking');self.assertTrue(iris['conversation']['sourceId']);scene=p.evaluate("__icarusSoak.observation().rooms.find(r=>r.id==='C05')");self.assertEqual(set(x['state'] for x in scene['actors']),{'talk','listen'});self.assertLess(abs(scene['actors'][0]['x']-scene['actors'][1]['x']),40);self.assertEqual(s['resourceAudit'],[])
 def test_protocol_four_previews_rotation_pin_promotion_and_pure_views(self):
  p=self.page();p.evaluate('__icarusSoak.save()');p.clock.install();p.reload();p.wait_for_function('!!window.__icarusSoak');self.operations(p);p.wait_for_selector('.obs-previews');self.assertEqual(p.locator('.obs-preview').count(),4);before=self.snap(p);p.locator('.obs-preview .obs-promote').first.click();selected=p.evaluate('ICARUSObservationLive.camera.selected');p.locator('.obs-previews').scroll_into_view_if_needed();p.wait_for_timeout(200);p.clock.fast_forward(13000);self.assertEqual(p.evaluate('ICARUSObservationLive.camera.selected'),selected);self.assertNotEqual(p.locator('.obs-preview').first.get_attribute('data-room'),selected);p.locator('.obs-rotation').click();bank=p.evaluate('ICARUSObservationLive.camera.bank');p.clock.fast_forward(13000);self.assertEqual(p.evaluate('ICARUSObservationLive.camera.bank'),bank);self.assertEqual(self.snap(p),before)
 def test_protocol_private_rooms_have_no_main_preview_or_remote_actors(self):
  p=self.page();self.configure(p,"""const q=s.crew[0];q.room=q.target='A05';q.route=[];q.nav=null;""");v=p.evaluate('__icarusSoak.observation()');self.assertEqual(v['rooms'][4]['actors'],[]);self.assertFalse(v['rooms'][4]['camera']);self.operations(p);p.wait_for_selector('.obs-select');options=p.locator('.obs-select option').all_text_contents();self.assertFalse(any('Crew Quarters' in x for x in options));before=self.snap(p);p.evaluate("ICARUSObservationLive.camera.pick('A05')");self.assertNotEqual(p.evaluate('ICARUSObservationLive.camera.selected'),'A05');self.assertEqual(self.snap(p),before)
 def test_protocol_room_lighting_is_actual_saved_state_and_no_false_bio(self):
  p=self.page();self.deck(p,'ship','overview');p.locator('.schematic-deck [data-room="C05"]').click();self.assertIn('No biological sensor model',p.locator('.schematic-detail').inner_text());self.assertIn('21.0',p.locator('.schematic-detail').inner_text());p.locator('.schematic-detail select').select_option('0.25');self.assertEqual(self.snap(p)['roomLighting']['C05'],.25);s=self.snap(p);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s);self.assertEqual(p.evaluate("__icarusSoak.observation().rooms.find(r=>r.id==='C05').lighting"),.25)
 def test_protocol_bridge_pause_and_header_widgets_accessible(self):
  p=self.page();self.assertTrue(p.locator('#pause').is_visible());self.assertFalse(p.evaluate('ICARUSBridgeMode.creator'));p.locator('#pause').click();self.assertIn('Pause',p.locator('#pause').inner_text());p.locator('#pause').click();self.assertIn('Resume',p.locator('#pause').inner_text());self.assertEqual(p.locator('.workspace-collapse').count(),0);heads=p.locator('.home-widget h3[role="button"]');self.assertGreater(heads.count(),0);head=heads.first;head.click();self.assertEqual(head.get_attribute('aria-expanded'),'false');head.focus();p.keyboard.press('Enter');self.assertEqual(head.get_attribute('aria-expanded'),'true')
 def test_protocol_crew_menu_and_mobile_no_world_mutation(self):
  p=self.page();self.operations(p);p.locator('.obs-crew>summary').click();before=self.snap(p);p.locator('.crew-quick summary').first.click();p.locator('.crew-quick[open] button').filter(has_text='Psychological assessment').click();self.assertIn('#deck/personnel/',p.url);self.assertEqual(self.snap(p),before);p.set_viewport_size({'width':390,'height':844});self.operations(p);p.wait_for_timeout(200);self.assertLessEqual(p.evaluate('document.documentElement.scrollWidth'),392);self.assertEqual(self.snap(p),before)
